sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    // ==========================================
    // FILTERS
    // ==========================================

    c.filters = {

        search: "",

        opportunity: ""

    };


    // ==========================================
    // FILTERED OFFERS
    // ==========================================

    c.filteredOffers = [];


    // ==========================================
    // OPPORTUNITY FILTER LIST
    // ==========================================

    c.opportunityList = [];


    // ==========================================
    // BUILD OPPORTUNITY LIST
    // ==========================================

    c.buildOpportunityList = function() {

        var offers =
            c.data.offers || [];

        var map = {};

        c.opportunityList = [];


        offers.forEach(function(offer) {

            if (
                offer.opportunity_sys_id &&
                !map[offer.opportunity_sys_id]
            ) {

                map[
                    offer.opportunity_sys_id
                ] = true;


                c.opportunityList.push({

                    id:
                        offer.opportunity_sys_id,

                    title:
                        offer.opportunity_title

                });

            }

        });

    };


    // ==========================================
    // APPLY FILTERS
    // ==========================================

    c.applyFilters = function() {

        var offers =
            c.data.offers || [];


        var search =
            (
                c.filters.search ||
                ""
            )
            .toLowerCase()
            .trim();


        var opportunity =
            c.filters.opportunity ||
            "";


        c.filteredOffers =
            offers.filter(function(offer) {


                // --------------------------------
                // SEARCH
                // --------------------------------

                var student =
                    (
                        offer.student_name ||
                        ""
                    ).toLowerCase();


                var applicationId =
                    (
                        offer.application_id ||
                        ""
                    ).toLowerCase();


                var opportunityTitle =
                    (
                        offer.opportunity_title ||
                        ""
                    ).toLowerCase();


                var opportunityId =
                    (
                        offer.opportunity_id ||
                        ""
                    ).toLowerCase();


                var matchesSearch =
                    !search ||

                    student.indexOf(search) !== -1 ||

                    applicationId.indexOf(search) !== -1 ||

                    opportunityTitle.indexOf(search) !== -1 ||

                    opportunityId.indexOf(search) !== -1;


                // --------------------------------
                // OPPORTUNITY
                // --------------------------------

                var matchesOpportunity =
                    !opportunity ||

                    offer.opportunity_sys_id ===
                    opportunity;


                return (
                    matchesSearch &&
                    matchesOpportunity
                );

            });

    };


    // ==========================================
    // CLEAR FILTERS
    // ==========================================

    c.clearFilters = function() {

        c.filters.search = "";

        c.filters.opportunity = "";

        c.applyFilters();

    };


    // ==========================================
    // INITIALIZE
    // ==========================================

    $scope.$watch(

        function() {

            return c.data.offers;

        },

        function(newValue) {

            if (newValue) {

                c.buildOpportunityList();

                c.applyFilters();

            }

        },

        true

    );

};

sp_widget.css:
.offers-page {
    padding: 30px;
    max-width: 1200px;
    margin: auto;
    color: #0b2a5b;
}


/* =========================================
   HEADER
========================================= */

.page-header {
    background: #ffffff;
    border: 1px solid #dbe3f3;
    border-radius: 18px;
    padding: 32px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 8px 25px rgba(40, 60, 100, 0.06);
}


.eyebrow {
    font-size: 11px;
    letter-spacing: 3px;
    font-weight: 700;
    color: #4e5ff5;
}


.page-header h1 {
    margin: 8px 0 5px;
    font-size: 28px;
}


.page-header p {
    margin: 0;
    color: #64748b;
}


.company-info {
    display: inline-block;
    margin-top: 14px;
    padding: 8px 14px;
    background: #f1f3ff;
    border-radius: 7px;
    font-size: 12px;
    color: #4054d9;
}


/* =========================================
   BUTTON
========================================= */

.btn {
    padding: 11px 18px;
    border-radius: 8px;
    text-decoration: none;
    font-size: 13px;
}


.btn-secondary {
    border: 1px solid #ccd6ed;
    background: #ffffff;
    color: #3155df;
}


/* =========================================
   STATISTICS
========================================= */

.stats-grid {
    display: grid;
    grid-template-columns:
        repeat(4, 1fr);

    gap: 18px;
    margin-top: 24px;
}


.stat-card {
    background: #ffffff;
    border: 1px solid #dbe3f3;
    border-radius: 16px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 14px;
}


.stat-icon {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #eef1ff;
    color: #4e5ff5;
    font-size: 18px;
}


.stat-icon.offered {
    background: #eefaf4;
    color: #1a9b5d;
}


.stat-icon.accepted {
    background: #eefaf4;
    color: #14844b;
}


.stat-icon.rejected {
    background: #fff0f0;
    color: #d94848;
}


.stat-label {
    font-size: 12px;
    color: #64748b;
}


.stat-value {
    margin-top: 4px;
    font-size: 22px;
    font-weight: 700;
}


/* =========================================
   FILTERS
========================================= */

.offer-filters {
    margin-top: 24px;
    padding: 16px;
    border: 1px solid #dbe3f3;
    background: #f8faff;
    border-radius: 14px;

    display: grid;

    grid-template-columns:
        1fr 260px 90px;

    gap: 12px;
}


.search-box,
.filter-box {
    position: relative;
}


.search-box input,
.filter-box select {
    width: 100%;
    height: 42px;
    border: 1px solid #ccd7ec;
    border-radius: 8px;
    background: #ffffff;
    padding: 0 14px;
    font-size: 13px;
    color: #19355f;
}


.search-box input {
    padding-left: 36px;
}


.search-icon {
    position: absolute;
    left: 13px;
    top: 11px;
    color: #52658a;
}


.clear-filter-btn {
    height: 42px;
    border: 1px solid #ccd7ec;
    border-radius: 8px;
    background: #ffffff;
    color: #3155df;
    cursor: pointer;
}


.filter-result {
    margin: 12px 2px;
    font-size: 12px;
    color: #64748b;
}


/* =========================================
   LIST CARD
========================================= */

.list-card {
    margin-top: 8px;
    background: #ffffff;
    border: 1px solid #dbe3f3;
    border-radius: 18px;
    overflow: hidden;
}


.list-header {
    padding: 24px;
    display: flex;
    justify-content: space-between;
    border-bottom: 1px solid #e5eaf3;
}


.list-header h2 {
    margin: 0;
    font-size: 18px;
}


.list-header p {
    margin: 6px 0 0;
    font-size: 12px;
    color: #64748b;
}


.record-count {
    padding: 8px 12px;
    background: #f1f3ff;
    color: #4054d9;
    border-radius: 8px;
    font-size: 12px;
}


/* =========================================
   TABLE
========================================= */

.table-wrapper {
    overflow-x: auto;
}


.offer-table {
    width: 100%;
    border-collapse: collapse;
}


.offer-table th {
    background: #f7f9fd;
    padding: 14px;
    text-align: left;
    font-size: 10px;
    letter-spacing: 1px;
    color: #637391;
}


.offer-table td {
    padding: 17px 14px;
    border-top: 1px solid #edf0f6;
    font-size: 12px;
    color: #35486c;
}


.student-cell {
    display: flex;
    align-items: center;
    gap: 10px;
}


.student-cell strong {
    display: block;
    color: #0b2a5b;
}


.student-cell span {
    display: block;
    margin-top: 3px;
    color: #7b8aa6;
    font-size: 10px;
}


.student-avatar {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: #eef1ff;
    color: #4054d9;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
}


.application-id {
    color: #4054d9;
}


.opportunity-cell strong {
    display: block;
    color: #0b2a5b;
}


.opportunity-cell span {
    display: block;
    margin-top: 4px;
    color: #7b8aa6;
    font-size: 10px;
}


.interview-cell strong {
    display: block;
    color: #15945a;
}


.interview-cell span {
    display: block;
    margin-top: 4px;
    color: #7b8aa6;
    font-size: 10px;
}


/* =========================================
   STATUS
========================================= */

.status-badge {
    display: inline-block;
    padding: 7px 12px;
    border-radius: 20px;
    font-size: 10px;
    font-weight: 600;
}


.status-offered {
    background: #eaf8f0;
    color: #16884f;
}


/* =========================================
   EMPTY
========================================= */

.empty-state {
    text-align: center;
    padding: 60px 20px;
}


.empty-icon {
    font-size: 30px;
    color: #7b88e8;
}


.empty-state h3 {
    margin: 12px 0 6px;
}


.empty-state p {
    color: #71809d;
    font-size: 13px;
}


/* =========================================
   RESPONSIVE
========================================= */

@media(max-width: 900px) {

    .stats-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }


    .offer-filters {
        grid-template-columns: 1fr;
    }

}

sp_widget.script:
(function() {

    // =====================================================
    // CAMPUS360 RECRUITER OFFERS
    // =====================================================

    // Current recruiter
    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';


    // =====================================================
    // CURRENT COMPANY
    // =====================================================

    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord('x_snc_campus360_company_master');


    if (!companyGR.get(companySysId)) {

        data.error =
            'Company record could not be found.';

        return;

    }


    data.company_name =
        companyGR.getValue('company_name');

    data.company_id =
        companyGR.getValue('company_id');


    // =====================================================
    // INITIAL VALUES
    // =====================================================

    data.total_count = 0;
    data.offered_count = 0;
    data.accepted_count = 0;
    data.rejected_count = 0;

    data.offers = [];


    // =====================================================
    // GET STUDENT APPLICATIONS
    // =====================================================
    //
    // Application
    //      ↓
    // Opportunity
    //      ↓
    // Company
    //
    // Only applications belonging to this company.
    //
    // Then:
    //
    // Offer Status = Offered
    //
    // AND
    //
    // Recruiter Interview Result = Selected
    //
    // for the SAME student + opportunity.
    //
    // =====================================================

    var applicationGR =
        new GlideRecord(
            'x_snc_campus360_student_application'
        );


    applicationGR.addQuery(
        'opportunity.company',
        companySysId
    );


    applicationGR.orderByDesc(
        'sys_created_on'
    );


    applicationGR.query();


    while (applicationGR.next()) {


        // =================================================
        // CHECK OFFER STATUS
        // =================================================

        var offerStatusDisplay =
            applicationGR.getDisplayValue(
                'offer_status'
            );


        /*
         * Only Offered applications should appear
         * in the Offers page.
         */

        if (offerStatusDisplay != 'Offered') {

            continue;

        }


        // =================================================
        // STUDENT
        // =================================================

        var studentSysId =
            applicationGR.getValue('student');


        if (!studentSysId) {

            continue;

        }


        var studentName =
            applicationGR.student.getDisplayValue();


        // =================================================
        // OPPORTUNITY
        // =================================================

        var opportunitySysId =
            applicationGR.getValue('opportunity');


        if (!opportunitySysId) {

            continue;

        }


        var opportunityGR =
            applicationGR.opportunity.getRefRecord();


        if (
            !opportunityGR ||
            !opportunityGR.isValidRecord()
        ) {

            continue;

        }


        // =================================================
        // VERIFY COMPANY
        // =================================================

        if (
            opportunityGR.getValue('company') !=
            companySysId
        ) {

            continue;

        }


        // =================================================
        // CHECK RECRUITER INTERVIEW
        // =================================================
        //
        // Same:
        //      Student
        //      Opportunity
        //
        // Interview Result must be Selected.
        //
        // =================================================

        var interviewGR =
            new GlideRecord(
                'x_snc_campus360_recruiter_interview'
            );


        interviewGR.addQuery(
            'student',
            studentSysId
        );


        interviewGR.addQuery(
            'opportunity',
            opportunitySysId
        );


        interviewGR.query();


        var selectedInterviewFound = false;
        var selectedInterview = null;


        while (interviewGR.next()) {

            var resultDisplay =
                interviewGR.getDisplayValue(
                    'result'
                );


            if (resultDisplay == 'Selected') {

                selectedInterviewFound = true;

                selectedInterview =
                    interviewGR.getUniqueValue();

                break;

            }

        }


        /*
         * If interview result is not Selected,
         * don't show the application as an offer.
         */

        if (!selectedInterviewFound) {

            continue;

        }


        // =================================================
        // BUILD OFFER RECORD
        // =================================================

        var offer = {};


        // -----------------------------------------------
        // APPLICATION
        // -----------------------------------------------

        offer.application_sys_id =
            applicationGR.getUniqueValue();


        offer.application_id =
            applicationGR.getValue(
                'application_id'
            );


        // -----------------------------------------------
        // STUDENT
        // -----------------------------------------------

        offer.student_sys_id =
            studentSysId;


        offer.student_name =
            studentName;


        // -----------------------------------------------
        // OPPORTUNITY
        // -----------------------------------------------

        offer.opportunity_sys_id =
            opportunitySysId;


        offer.opportunity_title =
            opportunityGR.getValue(
                'opportunity_title'
            );


        offer.opportunity_id =
            opportunityGR.getValue(
                'opportunity_id'
            );


        offer.location =
            opportunityGR.getValue(
                'location'
            );


        offer.ctc =
            opportunityGR.getValue(
                'ctc_stipend'
            );


        // -----------------------------------------------
        // APPLICATION DETAILS
        // -----------------------------------------------

        offer.application_status =
            applicationGR.getDisplayValue(
                'application_status'
            );


        offer.offer_status =
            offerStatusDisplay;


        offer.applied_date =
            applicationGR.getDisplayValue(
                'applied_date'
            );


        // -----------------------------------------------
        // INTERVIEW DETAILS
        // -----------------------------------------------

        offer.interview_sys_id =
            selectedInterview;


        var selectedInterviewGR =
            new GlideRecord(
                'x_snc_campus360_recruiter_interview'
            );


        if (
            selectedInterviewGR.get(
                selectedInterview
            )
        ) {

            offer.interview_date =
                selectedInterviewGR.getDisplayValue(
                    'interview_date'
                );


            offer.interview_round =
                selectedInterviewGR.getDisplayValue(
                    'interview_round'
                );


            offer.interview_mode =
                selectedInterviewGR.getDisplayValue(
                    'interview_mode'
                );


            offer.interviewer =
                selectedInterviewGR.getValue(
                    'interviewer'
                );


            offer.interview_result =
                selectedInterviewGR.getDisplayValue(
                    'result'
                );

        }


        // -----------------------------------------------
        // ADD OFFER
        // -----------------------------------------------

        data.offers.push(
            offer
        );


        data.total_count++;


        // -----------------------------------------------
        // OFFER STATUS COUNTS
        // -----------------------------------------------

        var applicationOfferStatus =
            applicationGR.getDisplayValue(
                'offer_status'
            );


        if (
            applicationOfferStatus ==
            'Offered'
        ) {

            data.offered_count++;

        }


        if (
            applicationOfferStatus ==
            'Accepted'
        ) {

            data.accepted_count++;

        }


        if (
            applicationOfferStatus ==
            'Rejected'
        ) {

            data.rejected_count++;

        }

    }


})();
